export const BASE_URL = "https://www.bulgogibillys.com";

/**
 * The link-preview photo when a page doesn't pick one: a 1.91:1 JPEG cut of
 * the bulgogi fries, generated by `npm run images` (a src/test assertion keeps
 * this path in step with the site's image registry, which shared/ can't import).
 */
export const DEFAULT_OG_IMAGE = `${BASE_URL}/images/opt/bulgogi-fries-og.jpg`;

interface PageMetaProps {
    title: string;
    description: string;
    /** Route path (e.g. "/menu") used to build the canonical URL. Omit for pages that shouldn't declare a canonical. */
    path?: string;
    /** Ask search engines not to index this page (admin, auth, not-found). */
    noindex?: boolean;
    /** Absolute URL of the link-preview image. */
    image?: string;
}

/**
 * Per-page head tags, hoisted into <head> by React 19 — and prerendered into
 * each page's HTML at build time, so link previews (iMessage, Slack, Facebook)
 * and crawlers that don't run JavaScript see the right title and photo.
 */
export default function PageMeta({
    title,
    description,
    path,
    noindex,
    image = DEFAULT_OG_IMAGE,
}: PageMetaProps) {
    const url = path !== undefined ? `${BASE_URL}${path}` : undefined;
    return (
        <>
            <title>{title}</title>
            <meta name="description" content={description} />
            {url && <link rel="canonical" href={url} />}
            {noindex && <meta name="robots" content="noindex" />}
            <meta property="og:type" content="website" />
            <meta property="og:title" content={title} />
            <meta property="og:description" content={description} />
            {url && <meta property="og:url" content={url} />}
            <meta property="og:image" content={image} />
            <meta name="twitter:card" content="summary_large_image" />
        </>
    );
}
